impl Solution {
    pub fn min_days(grid: Vec<Vec<i32>>) -> i32 {
        let m = grid.len();
        let n = grid[0].len();

        // Count islands in the grid
        fn count_islands(grid: &Vec<Vec<i32>>) -> i32 {
            let m = grid.len();
            let n = grid[0].len();
            let mut visited = vec![vec![false; n]; m];
            let directions = [(1,0), (-1,0), (0,1), (0,-1)];

            fn dfs(r: usize, c: usize, grid: &Vec<Vec<i32>>, visited: &mut Vec<Vec<bool>>, directions: &[(i32,i32)]) {
                visited[r][c] = true;
                for &(dr, dc) in directions {
                    let nr = r as i32 + dr;
                    let nc = c as i32 + dc;
                    if nr >= 0 && nr < grid.len() as i32 && nc >= 0 && nc < grid[0].len() as i32 {
                        let (nr, nc) = (nr as usize, nc as usize);
                        if !visited[nr][nc] && grid[nr][nc] == 1 {
                            dfs(nr, nc, grid, visited, directions);
                        }
                    }
                }
            }

            let mut islands = 0;
            for i in 0..m {
                for j in 0..n {
                    if grid[i][j] == 1 && !visited[i][j] {
                        islands += 1;
                        dfs(i, j, grid, &mut visited, directions);
                    }
                }
            }
            islands
        }

        // If already disconnected (0 or >1 islands), return 0
        let islands = count_islands(&grid);
        if islands == 0 || islands > 1 {
            return 0;
        }

        // Check if removing one land cell disconnects the island
        for i in 0..m {
            for j in 0..n {
                if grid[i][j] == 1 {
                    let mut new_grid = grid.clone();
                    new_grid[i][j] = 0;
                    let islands_after = count_islands(&new_grid);
                    if islands_after == 0 || islands_after > 1 {
                        return 1;
                    }
                }
            }
        }

        // Otherwise, minimum days is 2
        2
    }
}

